import re
from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class EthifParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_enableShaping()
        self.set_linkSelectorDN()

    def set_linkSelectorDN(self):
        srch = re.search(r"(\S+)/ETHIF-1", self.dist_name)
        self.set_parameter('linkSelectorDN', srch.group(1) + "/ETHLK-1")

    def set_enableShaping(self):
        srch = re.search(r"TNL-(\d+)/ETHSVC-1/ETHIF-1", self.dist_name)
        tnl_id = srch.group(1)
        if tnl_id == '3' or tnl_id == '6':
            self.set_parameter('enableShaping', 'false')
